-- PostgreSQL-oriented, migration-ready core schema for Milestone 1 planning.
-- UUIDs are internal identifiers; booking_no and quotation_no are permanent public identifiers.
create extension if not exists pgcrypto;

create table roles (id uuid primary key default gen_random_uuid(), name text not null unique, description text, active boolean not null default true, created_at timestamptz not null default now());
create table permissions (id uuid primary key default gen_random_uuid(), code text not null unique, description text not null);
create table role_permissions (role_id uuid not null references roles(id) on delete cascade, permission_id uuid not null references permissions(id) on delete cascade, primary key (role_id, permission_id));
create table users (id uuid primary key default gen_random_uuid(), role_id uuid references roles(id), full_name text not null, email text not null unique, password_hash text not null, active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());

create table customers (id uuid primary key default gen_random_uuid(), customer_no text not null unique, full_name text not null, nationality text, email text, phone text, whatsapp text, preferred_language text, assigned_user_id uuid references users(id), notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index customers_email_idx on customers(lower(email));
create index customers_phone_idx on customers(phone);
create table leads (id uuid primary key default gen_random_uuid(), lead_no text not null unique, customer_id uuid references customers(id), customer_name text not null, nationality text, email text, phone text, traveller_count int not null default 1 check (traveller_count > 0), expected_travel_date date, interested_package_id uuid, source text not null, assigned_user_id uuid references users(id), estimated_value numeric(12,2) not null default 0 check (estimated_value >= 0), status text not null, notes text, last_contact_at timestamptz, next_follow_up_at timestamptz, created_at timestamptz not null default now());
create index leads_status_followup_idx on leads(status, next_follow_up_at);
create table lead_activities (id uuid primary key default gen_random_uuid(), lead_id uuid not null references leads(id), customer_id uuid references customers(id), assigned_user_id uuid references users(id), activity_type text not null, scheduled_at timestamptz not null, notes text, status text not null default 'pending', created_at timestamptz not null default now());

create table product_categories (id uuid primary key default gen_random_uuid(), name text not null unique, active boolean not null default true, created_at timestamptz not null default now());
create table products (id uuid primary key default gen_random_uuid(), package_no text not null unique, name text not null, destination text, category_id uuid references product_categories(id), duration_days int, short_description text, full_description text, inclusions jsonb not null default '[]', exclusions jsonb not null default '[]', itinerary jsonb not null default '[]', min_pax int check (min_pax is null or min_pax > 0), max_pax int, booking_cutoff_hours int, status text not null default 'draft', internal_cost numeric(12,2), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table product_prices (id uuid primary key default gen_random_uuid(), product_id uuid not null references products(id), adult_price numeric(12,2) not null check (adult_price >= 0), child_price numeric(12,2) check (child_price is null or child_price >= 0), single_supplement numeric(12,2) not null default 0, valid_from date not null, valid_to date, active boolean not null default true);
create table addons (id uuid primary key default gen_random_uuid(), name text not null unique, description text, price numeric(12,2) not null check (price >= 0), active boolean not null default true);
create table product_addons (product_id uuid not null references products(id) on delete cascade, addon_id uuid not null references addons(id) on delete cascade, primary key(product_id, addon_id));

create table quotations (id uuid primary key default gen_random_uuid(), quotation_no text not null unique, customer_id uuid not null references customers(id), lead_id uuid references leads(id), travel_start_date date, travel_end_date date, status text not null default 'draft', subtotal numeric(12,2) not null default 0, discount numeric(12,2) not null default 0, total numeric(12,2) not null default 0, deposit_required numeric(12,2) not null default 0, valid_until date, assigned_user_id uuid references users(id), notes text, created_at timestamptz not null default now());
create table quotation_items (id uuid primary key default gen_random_uuid(), quotation_id uuid not null references quotations(id) on delete cascade, product_id uuid references products(id), package_name_snapshot text not null, adult_qty int not null default 0 check (adult_qty >= 0), child_qty int not null default 0 check (child_qty >= 0), adult_unit_price numeric(12,2) not null, child_unit_price numeric(12,2), single_supplement numeric(12,2) not null default 0, line_total numeric(12,2) not null);

create table bookings (id uuid primary key default gen_random_uuid(), booking_no text not null unique, customer_id uuid not null references customers(id), quotation_id uuid references quotations(id), source text not null, booked_at timestamptz not null default now(), travel_start_date date not null, travel_end_date date, status text not null default 'draft', total_value numeric(12,2) not null default 0, deposit_required numeric(12,2) not null default 0, amount_paid numeric(12,2) not null default 0, outstanding_balance numeric(12,2) not null default 0, payment_status text not null default 'unpaid', assigned_user_id uuid references users(id), notes text);
create index bookings_travel_status_idx on bookings(travel_start_date, status);
create table booking_items (id uuid primary key default gen_random_uuid(), booking_id uuid not null references bookings(id) on delete cascade, product_id uuid references products(id), package_name_snapshot text not null, adult_qty int not null default 0, child_qty int not null default 0, adult_unit_price numeric(12,2) not null, child_unit_price numeric(12,2), single_supplement numeric(12,2) not null default 0, line_total numeric(12,2) not null);
create table booking_travellers (id uuid primary key default gen_random_uuid(), booking_id uuid not null references bookings(id) on delete cascade, full_name text not null, nationality text, date_of_birth date, traveller_type text not null, passport_number_encrypted text, passport_expiry date, notes text);
create table booking_addons (booking_id uuid not null references bookings(id) on delete cascade, addon_id uuid references addons(id), addon_name_snapshot text not null, unit_price numeric(12,2) not null, quantity int not null default 1, primary key(booking_id, addon_id));

create table payments (id uuid primary key default gen_random_uuid(), payment_no text not null unique, booking_id uuid not null references bookings(id), paid_at timestamptz not null, method text not null, reference_no text, amount numeric(12,2) not null check (amount > 0), payment_type text not null, status text not null default 'recorded', notes text, recorded_by uuid references users(id));
create index payments_booking_idx on payments(booking_id, paid_at);
create table operations (id uuid primary key default gen_random_uuid(), booking_id uuid not null unique references bookings(id), status text not null default 'pending_preparation', assigned_user_id uuid references users(id), notes text);
create table tasks (id uuid primary key default gen_random_uuid(), operation_id uuid not null references operations(id) on delete cascade, title text not null, task_type text not null, assigned_user_id uuid references users(id), due_at timestamptz, status text not null default 'pending', notes text);
create table supplier_types (id uuid primary key default gen_random_uuid(), name text not null unique, active boolean not null default true);
create table suppliers (id uuid primary key default gen_random_uuid(), supplier_no text not null unique, name text not null, supplier_type_id uuid references supplier_types(id), contact_person text, phone text, email text, services text, coverage_area text, notes text, status text not null default 'active');
create table audit_logs (id uuid primary key default gen_random_uuid(), user_id uuid references users(id), action text not null, entity_type text not null, entity_id uuid, old_value jsonb, new_value jsonb, created_at timestamptz not null default now());
create index audit_entity_idx on audit_logs(entity_type, entity_id, created_at desc);
